import {price,carDefaults,chaptersFor,EVENTS} from './data.mjs';
import {validateGameState} from './game-schema.mjs';
export const SCHEMA=1;
export const round=n=>Math.round((Number(n)||0)*100)/100;
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const validDate=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(new Date(d+'T12:00:00Z').getTime())&&new Date(d+'T12:00:00Z').toISOString().slice(0,10)===d;
export function initialState(){return {schema:SCHEMA,language:'en',onboarded:false,name:'Alex',versions:[],sessions:[],activeId:null,ledger:[],emergency:{enabled:false,monthly:0,months:3},notifications:false,disclaimer:false};}
export function activeProfile(state,date=today()){return [...state.versions].filter(v=>v.effective<=date).sort((a,b)=>a.effective.localeCompare(b.effective)||a.created.localeCompare(b.created)).at(-1)||null;}
export function convertedIncome(p){if(p.incomeCurrency===p.currency)return p.income;return p.currency==='MYR'?p.income*p.fx:p.income/p.fx;}
export function capacity(p){if(!p)return {income:0,raw:0,available:0};const income=convertedIncome(p),raw=income-p.fixed-p.living-p.discretionary-p.loans-p.emergency;return {income:round(income),raw:round(raw),available:round(Math.max(0,raw))};}
export function profileVersion(state,profile){const fields=['income','fixed','living','discretionary','loans','savings','reserves','emergency'];for(const k of fields)if(!Number.isFinite(profile[k])||profile[k]<0)throw Error('Enter valid non-negative amounts.');if(!validDate(profile.effective))throw Error('Choose an effective date.');if(!['MY','SG'].includes(profile.country)||!['MYR','SGD'].includes(profile.incomeCurrency))throw Error('Choose a valid country and currency.');if(profile.fx<=0||!validDate(profile.fxDate))throw Error('Enter a positive, dated exchange rate.');const p={...profile,currency:profile.country==='SG'?'SGD':'MYR',id:uid(),created:new Date().toISOString()};state.versions.push(p);return p;}
export function loan(principal,rate,years,method='reducing'){const months=Math.round(years*12);if(principal<0||rate<0||months<1)return {monthly:0,interest:0,total:0};const r=rate/1200;const monthly=method==='flat'?principal*(1+rate/100*years)/months:r===0?principal/months:principal*r/(1-(1+r)**(-months));return {monthly:round(monthly),interest:round(monthly*months-principal),total:round(monthly*months)};}
export function carCosts(c){const principal=Math.max(0,c.price-c.down),l=loan(principal,c.rate,c.years,c.method),energy=c.mileage*c.consumption/100*c.unitPrice;const lines=[['instalment',l.monthly],['energy',energy],['insurance',c.insurance/12],['roadTax',c.tax/12],['parking',c.parking],['tolls',c.tolls],['maintenance',c.maintenance],['tyres',c.tyres],['battery',c.battery],['repairs',c.repairs]];const monthly=round(lines.reduce((a,[,v])=>a+v,0));return {...l,principal,lines,ownership:monthly,additional:round(Math.max(0,monthly-Math.min(monthly,c.replacedTransport))),upfront:round(c.down+c.insurance+c.tax),annual:round(c.insurance+c.tax)};}
export function remainingLoan(c,paidMonths){const p=c.price-c.down,n=Math.round(c.years*12),m=Math.min(n,Math.max(0,paidMonths));if(c.method==='flat')return {principal:round(p*(1-m/n)),scheduledPayments:round(loan(p,c.rate,c.years,'flat').monthly*(n-m))};const r=c.rate/1200,pmt=loan(p,c.rate,c.years).monthly;const principal=r===0?p-pmt*m:p*(1+r)**m-pmt*((1+r)**m-1)/r;return {principal:round(Math.max(0,principal)),scheduledPayments:round(pmt*(n-m))};}
export function virtualCarValue(c,ownedMonths){const annual=c.condition==='new'?.15:.1;return {value:round(c.price*(1-annual)**(Math.max(0,ownedMonths)/12)),annualAssumption:annual};}
export function newSession(story,p,config={},random=Math.random){const id=uid();const events={};for(const e of EVENTS.filter(e=>e.story===story))events[e.id]={selected:random()<e.probability,resolved:false,resolution:null};return {id,story,country:p.country,currency:p.currency,created:today(),profileId:p.id,index:0,clock:0,config:story==='car'?{...carDefaults(p.country),...config}:config,twins:story==='baby'?(config.knownTwins===true||random()<.01):false,events,history:[],current:null,costOverrides:{},completed:false};}
export function session(state){return state.sessions.find(s=>s.id===state.activeId)||null;}
export function budgetItems(s,index=s.index){const ch=chaptersFor(s.story,s.country,s.config)[index];if(!ch)return [];let items=ch.keys.map(k=>price(k,s.country));if(s.story==='car'&&index===14){items=s.events['car-defect']?.selected?items:[];if(s.config.warranty)items=items.map(i=>({...i,typical:0,min:0,max:0,assumptions:'Covered by the configured simulated mechanical warranty; check real policy terms.'}));}if(s.story==='travel')items=items.map(it=>({...it,typical:s.config.budget?.[it.id]??it.typical,quantity:it.id==='hotel'?1:Math.max(1,s.config.travellers||1)}));
if(s.story==='baby')items=items.map(it=>{let q=1;if(s.twins){if(['diapers','wipes','milk','clothes','food','learning','cot','seat','childcare','preschool'].includes(it.id))q=2;else if(['consult','care','screen','delivery','postpartum','stroller','health'].includes(it.id))q=1.35;}const part=ch.deposit?.3:ch.balance?.7:1;return {...it,quantity:q,typical:round((s.config[it.id]??it.typical)*part),assumptions:ch.deposit?'30% deposit of editable total':ch.balance?'70% balance; deposit already budgeted':it.assumptions};});
return items.map(it=>({...it,quote:s.costOverrides[`${index}:${it.id}`]??null,expectedPaymentDate:s.story==='travel'?addDays(s.created,ch.deadlineDay):addDays(s.created,(ch.month-1)*30)}));}
export function itemTotal(items){return round(items.reduce((sum,it)=>sum+(it.quote??it.typical)*it.quantity,0));}
export function travelBudget(s){return chaptersFor('travel',s.country,s.config).reduce((sum,_,i)=>sum+itemTotal(budgetItems(s,i)),0);}
export function addDays(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
export function travelSchedule(s){let cum=0;return chaptersFor('travel',s.country,s.config).map((c,i)=>{const snapshot=s.history.find(h=>h.index===i)||(s.current?.index===i?s.current:null);const cost=snapshot?snapshot.simulatedCost:itemTotal(budgetItems(s,i));cum+=cost;const gap=Math.max(0,cum-(s.config.existing||0));return {title:c.title,day:c.deadlineDay,date:addDays(s.created,c.deadlineDay),cost,cumulative:round(cum),needed:round(gap),daily:round(gap/Math.max(1,c.deadlineDay))};}).filter(r=>r.cost>0);}
export function accepted(state,currency){return state.ledger.filter(t=>t.status==='confirmed'&&t.currency===currency);}
export function allocation(state,sid,currency){return round(accepted(state,currency).reduce((n,t)=>n+(sid==='emergency'?t.emergency:t.storyId===sid?t.main:0),0));}
export function recordedSavings(state,p){return round(p.savings+accepted(state,p.currency).filter(t=>t.date>=p.effective&&!(p.excludedTransactionIds||[]).includes(t.id)).reduce((n,t)=>n+t.main,0));}
export function reserves(state,p){return round(p.reserves+accepted(state,p.currency).filter(t=>t.date>=p.effective&&!(p.excludedTransactionIds||[]).includes(t.id)).reduce((n,t)=>n+t.emergency,0));}
export function challenge(s,p,index=s.index,choice=null){const ch=chaptersFor(s.story,s.country,s.config)[index];const cap=capacity(p).available;const car=s.story==='car'?carCosts(s.config):null;const repairExtra=s.story==='car'&&index===14?Math.max(0,itemTotal(budgetItems(s,index))-s.config.repairs*Math.max(0,index-4)):0;const raw=car?round(index===4?car.upfront:car.additional+repairExtra):round(itemTotal(budgetItems(s,index))*(choice?.factor??1));const already=s.history.reduce((n,h)=>n+h.target,0);let need=raw;if(s.story==='travel'){const previous=s.history.reduce((n,h)=>n+h.simulatedCost,0);const existing=Math.max(0,(s.config.existing||0)-previous);need=Math.max(0,raw-existing);}
// Monthly capacity is not the same as a daily target. Travel uses the time until each booking.
let interval=s.story==='travel'?Math.max(1,(ch.deadlineDay-(index?chaptersFor(s.story,s.country,s.config)[index-1].deadlineDay:0))):30;
const affordable=s.story==='travel'?cap*interval/30:cap;const target=round(Math.min(need,Math.max(0,affordable)));return {raw:round(raw),need:round(need),target,requiredTotal:round(already+target),shortfall:round(Math.max(0,need-target)),months:cap>0?Math.ceil(need/cap):null,profileId:p.id,interval};}
export function decide(s,p,choiceId){if(s.current)throw Error('This chapter decision is already saved.');if(p.currency!==s.currency)throw Error('The financial profile and story currencies must match.');const ch=chaptersFor(s.story,s.country,s.config)[s.index],choice=ch.choices.find(c=>c.id===choiceId);if(!choice)throw Error('Choose an available decision.');if(choice.tag==='cheaper'){s.config.price=round(s.config.price*.8);s.config.down=Math.min(s.config.down,s.config.price);s.config.insurance=round(s.config.insurance*.9);}if(choice.tag==='efficient')s.config.mileage=round(s.config.mileage*.9);if(choice.tag==='insuranceSaving')s.config.insurance=round(s.config.insurance*.9);const c=challenge(s,p,s.index,choice);s.current={index:s.index,title:ch.title,choice:{...choice},items:budgetItems(s).map(it=>({...it})),simulatedCost:c.raw,target:c.target,requiredTotal:c.requiredTotal,shortfall:c.shortfall,profileId:p.id,currency:s.currency,decided:today(),dueDay:s.story==='travel'?ch.deadlineDay:Math.max(s.clock+30,ch.month*30)+(choice.tag==='extend'?30:0)};return s.current;}
export function reviseCheckpoint(s,p,target,extraDays=0){if(!s.current||!Number.isFinite(target)||target<0||!Number.isFinite(extraDays)||extraDays<0)throw Error('Enter a valid savings target and extension.');if(p.currency!==s.currency)throw Error('The profile currency must match the story.');if(target>s.current.target+.005)throw Error('Use this adjustment only to lower the checkpoint.');const cap=capacity(p).available;if(target>cap*(1+extraDays/30)+.005)throw Error('The adjusted contribution exceeds capacity for this preparation period.');const c=s.current;s.adjustments??=[];s.adjustments.push({index:s.index,oldTarget:c.target,target,extraDays,profileId:p.id,date:today()});c.target=round(target);c.requiredTotal=round(s.history.reduce((n,h)=>n+h.target,0)+target);c.shortfall=round(Math.max(0,c.simulatedCost-target));c.dueDay+=extraDays;c.adjustedProfileId=p.id;return c;}
export function canAdvance(state,s){if(!s?.current||s.completed)return false;const event=eventFor(s);return s.clock>=s.current.dueDay&&allocation(state,s.id,s.currency)+.005>=s.current.requiredTotal&&(!event||event.resolved);}
export function advance(state,s){if(!canAdvance(state,s))throw Error('Finish your decision, Savings Day, and any event first.');s.history.push({...s.current,completed:today()});s.current=null;s.index++;if(s.index>=chaptersFor(s.story,s.country,s.config).length)s.completed=true;return s;}
export function eventFor(s){const def=EVENTS.find(e=>e.story===s.story&&e.chapters.includes(s.index)&&s.events[e.id]?.selected&&!s.events[e.id].resolved);if(!def)return null;if(def.id==='car-defect'&&s.index===2&&s.current?.choice.id!=='inspect')return null;return {...def,...s.events[def.id]};}
export function resolveEvent(s,id,resolution){const e=EVENTS.find(e=>e.id===id&&e.story===s.story);if(!e||!e.choices.includes(resolution))throw Error('Choose a valid response.');s.events[id]={...s.events[id],resolved:true,resolution,at:s.index};}
export function submitTransaction(state,t){for(const k of ['amount','main','emergency'])if(!Number.isFinite(t[k])||t[k]<0)throw Error('Amounts must be valid and non-negative.');if(t.amount<=0||t.main+t.emergency>t.amount+.001||t.main+t.emergency===0)throw Error('Allocate a positive amount, no more than the transaction total.');if(!t.reference?.trim()||t.reference.trim().length<3)throw Error('Enter a reference of at least three characters.');if(t.date>today()||!validDate(t.date))throw Error('Use an actual transfer date, today or earlier.');if(t.main>0&&!state.sessions.some(s=>s.id===t.storyId&&s.currency===t.currency))throw Error('Choose an active story in this currency.');if(t.emergency>0&&!state.emergency.enabled)throw Error('Enable your emergency plan first.');if(state.ledger.some(x=>x.status!=='rejected'&&((x.reference.trim().toLowerCase()===t.reference.trim().toLowerCase())||(t.hash&&x.hash===t.hash))))throw Error('This reference or evidence has already been submitted.');const entry={...t,reference:t.reference.trim(),id:uid(),status:'pending',created:new Date().toISOString()};state.ledger.push(entry);return entry;}
export function confirmTransaction(state,id){const t=state.ledger.find(x=>x.id===id);if(!t||t.status!=='pending')throw Error('Only pending records can be confirmed.');t.status='confirmed';t.verifiedBy='local-self-confirmation';t.confirmed=new Date().toISOString();return t;}
export function validateImport(s){
const fail=()=>{throw Error('Unsupported or invalid journal backup.');};
const amount=x=>Number.isFinite(x)&&x>=0;
const title=x=>x&&typeof x.en==='string'&&typeof x.zh==='string';
if(!s||s.schema!==SCHEMA||typeof s.name!=='string'||s.name.length>80||!['en','zh'].includes(s.language)||!Array.isArray(s.versions)||!Array.isArray(s.sessions)||!Array.isArray(s.ledger)||!s.emergency||!amount(s.emergency.monthly)||!amount(s.emergency.months)||s.emergency.months>120||typeof s.emergency.enabled!=='boolean')fail();
const copy=initialState(),versions=new Set(),sessions=new Set(),transactions=new Set(),refs=new Set(),hashes=new Set();
for(const p of s.versions){if(typeof p.id!=='string'||versions.has(p.id)||typeof p.created!=='string'||p.currency!==(p.country==='SG'?'SGD':'MYR')||!validDate(p.effective))fail();profileVersion(copy,p);versions.add(p.id);}
for(const x of s.sessions){if(!(x.mode==='v2'?['car','travel','baby','home','wedding','business','education','living','retirement','emergency']:['car','travel','baby']).includes(x.story)||!['MY','SG'].includes(x.country)||(x.mode==='v2'?!['MYR','SGD'].includes(x.currency):x.currency!==(x.country==='MY'?'MYR':'SGD'))||typeof x.id!=='string'||sessions.has(x.id)||!versions.has(x.profileId)||!validDate(x.created)||!Number.isInteger(x.index)||!amount(x.clock)||!Array.isArray(x.history)||!x.events||!x.costOverrides||!x.config||typeof x.completed!=='boolean')fail();
if(x.story==='car'){for(const k of Object.keys(carDefaults(x.country)).filter(k=>typeof carDefaults(x.country)[k]==='number'))if(!amount(x.config[k]))fail();if(x.config.down>x.config.price||x.config.years<1||!['flat','reducing'].includes(x.config.method))fail();}
if(x.story==='travel'&&(!amount(x.config.days)||x.config.days<30||x.config.days>365||!amount(x.config.travellers)||x.config.travellers<1))fail();
const count=x.mode==='v2'?120:chaptersFor(x.story,x.country,x.config).length;if(x.index>count||x.history.length!==x.index)fail();
for(const h of [...x.history,...(x.current?[x.current]:[])]){if(!Number.isInteger(h.index)||!title(h.title)||!h.choice||!title(h.choice.title)||!title(h.choice.detail)||!amount(h.target)||!amount(h.requiredTotal)||!amount(h.simulatedCost)||!Array.isArray(h.items)||!versions.has(h.profileId))fail();for(const i of h.items)if(!title(i.label)||!amount(i.typical)||!amount(i.quantity)||(i.quote!==null&&!amount(i.quote)))fail();}
sessions.add(x.id);}
for(const t of s.ledger){if(!['pending','confirmed','rejected'].includes(t.status)||!['MYR','SGD'].includes(t.currency)||typeof t.id!=='string'||transactions.has(t.id)||typeof t.reference!=='string'||!validDate(t.date)||![t.amount,t.main,t.emergency].every(amount)||t.main+t.emergency>t.amount+.001||(t.main>0&&!sessions.has(t.storyId)))fail();transactions.add(t.id);if(t.status!=='rejected'){const ref=t.reference.trim().toLowerCase();if(refs.has(ref)||(t.hash&&hashes.has(t.hash)))fail();refs.add(ref);if(t.hash)hashes.add(t.hash);}}
if(s.activeId&&!sessions.has(s.activeId))fail();return validateGameState(s);
}
